from math import exp
from itertools import product
expit=lambda x: 1/(1+exp(-x))
P={}
for h,v,c,r,y in product([0,1],repeat=5):
 phv=1/6 if h==v else 1/3
 pr=expit(.75*h+.5*c)
 py=expit(-.5+2.5*v+1.75*c)
 P[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def py1(**cond):
 idx={'h':0,'v':1,'c':2,'r':3}
 pairs=[(k,p) for k,p in P.items() if all(k[idx[a]]==b for a,b in cond.items())]
 return sum(p for k,p in pairs if k[4]==1)/sum(p for k,p in pairs)
print('P(Y=1|H=0), P(Y=1|H=1):',py1(h=0),py1(h=1))
for c in [0,1]:
 print(f'P(Y=1|C={c},R=0), P(Y=1|C={c},R=1):',py1(c=c,r=0),py1(c=c,r=1))
print('Bayes classification accuracy:',sum(max(expit(-.5+2.5*v+1.75*c),1-expit(-.5+2.5*v+1.75*c)) for v,c in product([0,1],repeat=2))/4)
print('Bird split sum:',2849+520+529)
PY"
